import random
from collections import defaultdict


class QLearningAgent:
    def __init__(self, learning_rate=0.1, discount_factor=0.9, epsilon=0.1):
        self.alpha = learning_rate
        self.gamma = discount_factor
        self.epsilon = epsilon
        self.qtable = defaultdict(float)

    def chooseAction(self, state, validActions):
        if random.random() < self.epsilon:
            return random.choice(validActions)
        else:
            maxQ = max(self.qtable[(state, a)] for a in validActions)
            bestActions = [a for a in validActions if self.qtable[(state, a)] == maxQ]
            return random.choice(bestActions)

    def updateQVal(self, state, action, reward, nextState, nextActions):
        oldQ = self.qtable[(state, action)]
        maxFutureQ = max((self.qtable[(nextState, a)] for a in nextActions), default=0)
        newQ = oldQ + self.alpha * (reward + self.gamma * maxFutureQ - oldQ)
        self.qtable[(state, action)] = newQ

    def getActions(self, environment):
        actions = []
        for action, delta in ACTION_DELTAS.items():
            newRow = environment.pos[0] + delta[0]
            newCol = environment.pos[1] + delta[1]
            if 0 <= newRow < len(environment.grid) and 0 <= newCol < len(environment.grid[0]):
                cell = environment.grid[newRow][newCol]
                if cell != "X":
                    actions.append(action)
        return actions


ACTION_DELTAS = {"UP": (-1, 0), "DOWN": (1, 0), "LEFT": (0, -1), "RIGHT": (0, 1)}
